\copy (select s.sheet_id, c.factors_json->>'momentum' momentum, c.factors_json->>'value' value, c.factors_json->>'quality' quality, c.factors_json->>'technical' technical, c.factors_json->>'supply_demand' supply_demand, c.factors_json->>'sector_momentum' sector_momentum, c.factors_json->>'news' news, c.factors_json->>'quant_total' quant_total from position_sheets s join screening_candidates c on c.promoted_to_sheet_id = s.sheet_id where s.generated_at >= '2026-08-15') to stdout with csv header
